#include <vector>
#include <deque>
#include <set>
#include <unordered_map>
#include <algorithm>

using namespace std;

class Router {
    int limit;
    deque<vector<int>> q;
    set<vector<int>> seen;
    unordered_map<int, vector<int>> destTimes;

public:
    Router(int memoryLimit) : limit(memoryLimit) {}

    bool addPacket(int source, int destination, int timestamp) {
        vector<int> pkt = {source, destination, timestamp};
        if (seen.count(pkt)) return false;

        if ((int)q.size() >= limit) {
            auto old = q.front(); q.pop_front();
            seen.erase(old);
            auto& vec = destTimes[old[1]];
            auto it = lower_bound(vec.begin(), vec.end(), old[2]);
            if (it != vec.end() && *it == old[2]) vec.erase(it);
        }
        q.push_back(pkt);
        seen.insert(pkt);
        auto& vec = destTimes[destination];
        vec.insert(upper_bound(vec.begin(), vec.end(), timestamp), timestamp);
        return true;
    }

    vector<int> forwardPacket() {
        if (q.empty()) return {};
        auto pkt = q.front(); q.pop_front();
        seen.erase(pkt);
        auto& vec = destTimes[pkt[1]];
        auto it = lower_bound(vec.begin(), vec.end(), pkt[2]);
        if (it != vec.end() && *it == pkt[2]) vec.erase(it);
        return pkt;
    }

    int getCount(int destination, int startTime, int endTime) {
        if (!destTimes.count(destination)) return 0;
        const auto& vec = destTimes[destination];
        auto l = lower_bound(vec.begin(), vec.end(), startTime);
        auto r = upper_bound(vec.begin(), vec.end(), endTime);
        return distance(l, r);
    }
};

import java.util.*;

class Router {
    private int limit;
    private ArrayDeque<int[]> q;
    private Set<String> seen;
    private Map<Integer, List<Integer>> destTimes;

    public Router(int memoryLimit) {
        this.limit = memoryLimit;
        this.q = new ArrayDeque<>();
        this.seen = new HashSet<>();
        this.destTimes = new HashMap<>();
    }

    public boolean addPacket(int source, int destination, int timestamp) {
        String key = source + "#" + destination + "#" + timestamp;
        if (seen.contains(key)) return false;

        if (q.size() >= limit) {
            int[] old = q.pollFirst();
            seen.remove(old[0] + "#" + old[1] + "#" + old[2]);
            List<Integer> list = destTimes.get(old[1]);
            if (list != null) {
                int idx = Collections.binarySearch(list, old[2]);
                if (idx >= 0) list.remove(idx);
            }
        }

        q.addLast(new int[]{source, destination, timestamp});
        seen.add(key);
        destTimes.computeIfAbsent(destination, k -> new ArrayList<>());
        List<Integer> list = destTimes.get(destination);
        int idx = Collections.binarySearch(list, timestamp);
        if (idx < 0) idx = -idx - 1;
        list.add(idx, timestamp);
        return true;
    }

    public int[] forwardPacket() {
        if (q.isEmpty()) return new int[0];
        int[] pkt = q.pollFirst();
        seen.remove(pkt[0] + "#" + pkt[1] + "#" + pkt[2]);
        List<Integer> list = destTimes.get(pkt[1]);
        if (list != null) {
            int idx = Collections.binarySearch(list, pkt[2]);
            if (idx >= 0) list.remove(idx);
        }
        return pkt;
    }

    public int getCount(int destination, int startTime, int endTime) {
        List<Integer> list = destTimes.get(destination);
        if (list == null || list.isEmpty()) return 0;
        int l = lowerBound(list, startTime);
        int r = upperBound(list, endTime);
        return r - l;
    }

    private int lowerBound(List<Integer> list, int val) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (list.get(mid) >= val) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }

    private int upperBound(List<Integer> list, int val) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (list.get(mid) > val) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
}

var Router = function(memoryLimit) {
    this.limit = memoryLimit;
    this.q = [];
    this.seen = new Set();
    this.destTimes = new Map();
};

Router.prototype.addPacket = function(source, destination, timestamp) {
    const key = `${source},${destination},${timestamp}`;
    if (this.seen.has(key)) return false;

    if (this.q.length >= this.limit) {
        const old = this.q.shift();
        this.seen.delete(`${old[0]},${old[1]},${old[2]}`);
        const list = this.destTimes.get(old[1]);
        if (list) {
            const idx = list.indexOf(old[2]);
            if (idx !== -1) list.splice(idx, 1);
        }
    }

    this.q.push([source, destination, timestamp]);
    this.seen.add(key);
    if (!this.destTimes.has(destination)) this.destTimes.set(destination, []);
    const list = this.destTimes.get(destination);
    let idx = 0;
    while (idx < list.length && list[idx] <= timestamp) idx++;
    list.splice(idx, 0, timestamp);
    return true;
};

Router.prototype.forwardPacket = function() {
    if (this.q.length === 0) return [];
    const pkt = this.q.shift();
    this.seen.delete(`${pkt[0]},${pkt[1]},${pkt[2]}`);
    const list = this.destTimes.get(pkt[1]);
    if (list) {
        const idx = list.indexOf(pkt[2]);
        if (idx !== -1) list.splice(idx, 1);
    }
    return pkt;
};

Router.prototype.getCount = function(destination, startTime, endTime) {
    const list = this.destTimes.get(destination);
    if (!list) return 0;
    let count = 0;
    for (const t of list) {
        if (t >= startTime && t <= endTime) count++;
    }
    return count;
};
